for kid, kind, rests, text in NEW:
    print(kid, run(["conclusion", "add", "--kind", kind, "--rests-on", rests, "--text", text]))
REPL = [("K001", "K029"), ("K009", "K029"), ("K003", "K030"), ("K027", "K031"), ("K008", "K031"), ("K004", "K032"), ("K017", "K033"), ("K026", "K035"), ("K012", "K036"), ("K010", "K037"), ("K013", "K038")]
for old, new in REPL:
    print(old, run(["conclusion", "set-status", old, "--status", "заменён", "--replaced-by", new]))
